def safe_int(campo: str, valor: str):
    texto = valor.strip()
    if texto == "":
        return False, None, f"ERROR en '{campo}': valor vacío"
    try:
        return True, int(texto), None
    except ValueError:
        return False, None, f"ERROR en '{campo}': no se pudo convertir {valor!r} a int"

def pipeline(edad_txt, anios_txt):
    raw = {"edad": edad_txt, "anios_cliente": anios_txt}
    clean = {}
    errors = []
    for campo, valor in raw.items():
        ok, numero, error = safe_int(campo, valor)
        clean[campo] = numero if ok else None
        if error is not None:
            errors.append(error)
    return {"raw": raw, "clean": clean, "errors": errors}

