    }

def parse_monto(texto: str):
    limpio = texto.strip()
    if limpio == "":
        return False, None, f"ERROR en 'monto': valor vacío (raw={texto!r})"
    try:
        monto = Decimal(limpio).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
        return True, monto, None
    except InvalidOperation:
        return False, None, f"ERROR en 'monto': no se pudo convertir {texto!r} a Decimal"

