def parse_nombres(valor: str) -> dict:
    clean = valor.strip()
    errors = []
    if clean == "":
        errors.append(f"ERROR en 'nombres': valor vacío (raw={valor!r})")
        clean = None
    return {"nombres_raw": valor, "nombres": clean, "errors": errors}
